/* Boot (sync in <head>): window.CNTU core — config, dom, storage, bus,
 * paths, theme (applied before first paint), i18n (language + dictionary).
 * GENERATED by scripts/build.mjs — edit the sources, then run `npm run build`. */

(() => {
  'use strict';

  const CNTU = (window.CNTU = window.CNTU || {});

  document.documentElement.classList.add('js');

  CNTU.config = Object.freeze({
    STORAGE_KEYS: Object.freeze({
      theme: 'site-theme',
      lang: 'site-lang',
      notice: 'notice-dismissed', // sessionStorage
      secrets: 'site-secrets',
    }),
    LANGS: Object.freeze(['uk', 'en', 'pl', 'de', 'es', 'ja']),
    LANG_NAMES: Object.freeze({
      uk: 'Українська',
      en: 'English',
      pl: 'Polski',
      de: 'Deutsch',
      es: 'Español',
      ja: '日本語',
    }),
    LEGACY_LANGS: Object.freeze({ ua: 'uk' }),
    DEFAULT_LANG: 'uk',
    MOBILE_MEDIA: '(max-width: 768px)',
    THEME_COLORS: Object.freeze({ light: '#1e3c72', dark: '#0f172a' }),
    EVENT_PREFIX: 'kntu:',
    REVEAL_TIMEOUT_MS: 3000,
  });

  CNTU.dom = Object.freeze({
    $: (selector, scope = document) => scope.querySelector(selector),
    $$: (selector, scope = document) => [...scope.querySelectorAll(selector)],
  });
})();

(() => {
  'use strict';

  const { STORAGE_KEYS } = window.CNTU.config;

  const getStorage = (type) => {
    try {
      return window[type];
    } catch {
      return null;
    }
  };

  const createStore = (storage) => ({
    get: (key) => {
      try {
        return storage ? storage.getItem(key) : null;
      } catch {
        return null;
      }
    },
    set: (key, value) => {
      try {
        storage?.setItem(key, value);
      } catch {
      }
    },
  });

  const local = createStore(getStorage('localStorage'));
  const session = createStore(getStorage('sessionStorage'));

  const listSecrets = () => {
    try {
      const list = JSON.parse(local.get(STORAGE_KEYS.secrets) ?? '[]');
      return Array.isArray(list) ? list : [];
    } catch {
      return [];
    }
  };

  const addSecret = (id) => {
    const found = listSecrets();
    if (found.includes(id)) return found;
    const next = [...found, id];
    local.set(STORAGE_KEYS.secrets, JSON.stringify(next));
    return next;
  };

  window.CNTU.storage = Object.freeze({
    local,
    session,
    secrets: Object.freeze({ list: listSecrets, add: addSecret }),
  });
})();

(() => {
  'use strict';

  const { EVENT_PREFIX } = window.CNTU.config;

  window.CNTU.bus = Object.freeze({
    on: (name, handler, options) =>
      document.addEventListener(EVENT_PREFIX + name, handler, options),
    emit: (name, detail) =>
      document.dispatchEvent(
        new CustomEvent(EVENT_PREFIX + name, detail === undefined ? undefined : { detail }),
      ),
  });
})();

(() => {
  'use strict';

  const FALLBACK_SCRIPTS_DIR = 'assets/js/';
  const self = document.currentScript;
  const scripts = self?.src ? self.src.replace(/[^/]*$/, '') : FALLBACK_SCRIPTS_DIR;

  window.CNTU.paths = Object.freeze({
    scripts,
    i18n: `${scripts}i18n/`,
  });
})();

(() => {
  'use strict';

  const { config, storage } = window.CNTU;
  const { STORAGE_KEYS, THEME_COLORS } = config;
  const DARK = 'dark';
  const LIGHT = 'light';
  const root = document.documentElement;
  const systemDark = window.matchMedia?.('(prefers-color-scheme: dark)') ?? null;

  const saved = () => {
    const value = storage.local.get(STORAGE_KEYS.theme);
    return value === DARK || value === LIGHT ? value : null;
  };

  const resolve = (value) => value === DARK || (value !== LIGHT && Boolean(systemDark?.matches));

  const isDark = () => root.dataset.theme === DARK;

  const render = (dark) => {
    if (dark) root.dataset.theme = DARK;
    else delete root.dataset.theme;
    document.getElementById('themeToggle')?.setAttribute('aria-pressed', String(dark));
    document
      .querySelector('meta[name="theme-color"]')
      ?.setAttribute('content', dark ? THEME_COLORS.dark : THEME_COLORS.light);
  };

  const set = (dark) => {
    render(dark);
    storage.local.set(STORAGE_KEYS.theme, dark ? DARK : LIGHT);
  };

  if (resolve(storage.local.get(STORAGE_KEYS.theme))) {
    root.setAttribute('data-theme', DARK);
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta && !root.classList.contains('is-night')) {
      meta.setAttribute('content', THEME_COLORS.dark);
    }
  }

  window.CNTU.theme = Object.freeze({ systemDark, saved, resolve, isDark, render, set });
})();

(() => {
  'use strict';

  const { config, storage, paths, bus } = window.CNTU;
  const { LANGS, LANG_NAMES, LEGACY_LANGS, DEFAULT_LANG, STORAGE_KEYS, REVEAL_TIMEOUT_MS } = config;
  const PENDING_CLASS = 'i18n-pending';
  const ATTR_PAIR_SEPARATOR = ';';
  const ATTR_KEY_SEPARATOR = ':';
  const root = document.documentElement;

  const dicts = {};
  const loading = {};
  const subscribers = new Set();
  const warned = new Set();
  let current = DEFAULT_LANG;
  let request = 0;

  const supported = (code) => {
    const lower = String(code ?? '').toLowerCase();
    const normalized = LEGACY_LANGS[lower] ?? lower;
    return LANGS.includes(normalized) ? normalized : null;
  };

  const register = (lang, dict) => {
    dicts[lang] = dict;
  };

  const load = (lang) => {
    const code = supported(lang) ?? DEFAULT_LANG;
    if (dicts[code]) return Promise.resolve(dicts[code]);
    if (loading[code]) return loading[code];
    loading[code] = new Promise((resolve) => {
      const script = document.createElement('script');
      script.src = `${paths.i18n}${code}.js`;
      script.onload = script.onerror = () => {
        if (!dicts[code]) delete loading[code];
        resolve(dicts[code] ?? null);
      };
      document.head.appendChild(script);
    });
    return loading[code];
  };

  const setText = (node, value) => {
    if (typeof value === 'string' && node.textContent !== value) node.textContent = value;
  };

  const setAttributes = (node, map) => {
    node
      .getAttribute('data-i18n-attr')
      .split(ATTR_PAIR_SEPARATOR)
      .forEach((pair) => {
        const [attr = '', key = ''] = pair.split(ATTR_KEY_SEPARATOR).map((part) => part.trim());
        const value = map[key];
        if (attr && typeof value === 'string' && node.getAttribute(attr) !== value) {
          node.setAttribute(attr, value);
        }
      });
  };

  const translate = (map, scope = document) => {
    if (!map) return;
    scope
      .querySelectorAll('[data-i18n]')
      .forEach((node) => setText(node, map[node.getAttribute('data-i18n')]));
    scope.querySelectorAll('[data-i18n-attr]').forEach((node) => setAttributes(node, map));
  };

  const pickLanguage = () => {
    const saved = supported(storage.local.get(STORAGE_KEYS.lang));
    if (saved) return saved;
    const prefs = navigator.languages?.length ? navigator.languages : [navigator.language];
    for (const pref of prefs) {
      const match = supported(String(pref ?? '').split('-')[0]);
      if (match) return match;
    }
    return DEFAULT_LANG;
  };

  const reveal = () => root.classList.remove(PENDING_CLASS);

  const t = (key, section = 'main') => {
    const value = dicts[current]?.[section]?.[key] ?? dicts[DEFAULT_LANG]?.[section]?.[key];
    if (value === undefined && dicts[current] && !warned.has(key)) {
      warned.add(key);
      console.warn(`[i18n] Missing translation key: "${key}"`);
    }
    return value;
  };

  const fill = (scope = document) => translate(dicts[current]?.main, scope);

  const apply = (nextLang) => {
    const code = supported(nextLang) ?? DEFAULT_LANG;
    request += 1;
    const id = request;
    return load(code).then((dict) => {
      if (id !== request) return current;
      current = dict ? code : DEFAULT_LANG;
      root.lang = current;
      fill();
      subscribers.forEach((fn) => fn(current));
      bus.emit('lang-changed', { lang: current });
      reveal();
      return current;
    });
  };

  const onChange = (fn) => subscribers.add(fn);

  const initial = pickLanguage();
  current = initial;
  root.lang = initial;
  const ready = load(initial);

  if (initial !== DEFAULT_LANG) {
    root.classList.add(PENDING_CLASS);
    const domReady = new Promise((resolve) => {
      if (document.readyState !== 'loading') resolve();
      else document.addEventListener('DOMContentLoaded', resolve, { once: true });
    });
    Promise.all([ready, domReady]).then(() => window.setTimeout(reveal, 0));
    window.setTimeout(reveal, REVEAL_TIMEOUT_MS);
  }

  window.CNTU.i18n = Object.freeze({
    langs: LANGS,
    names: LANG_NAMES,
    defaultLang: DEFAULT_LANG,
    dicts,
    initial,
    get lang() {
      return current;
    },
    ready,
    supported,
    register,
    load,
    translate,
    t,
    fill,
    apply,
    onChange,
  });
})();
